import { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Container, TextField, Button, Typography,
  Paper, Box, MenuItem, FormControl,
  InputLabel, Select
} from '@mui/material';
import { useParams, useNavigate } from 'react-router-dom';

export default function UpdateProduct() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [product, setProduct] = useState({
    name: "",
    description: "",
    price: "",
    quantity: "",
    categoryId: "",
    productimage: null
  });

  const [category, setCategory] = useState([]);
  const [previewImage, setPreviewImage] = useState(null); // shows existing image

  // ✅ Fetch categories for dropdown
  useEffect(() => {
    axios.get("http://localhost:7000/category/getCategory")
      .then((res) => {
        setCategory(res.data.data || []);
      })
      .catch((err) => console.log(err));
  }, []);

  // ✅ Fetch existing product data to prefill the form
  useEffect(() => {
    axios.get(`http://localhost:7000/product/getProductById/${id}`)
      .then((res) => {
        const data = res.data.data || res.data;
        setProduct({
          name: data.name || "",
          description: data.description || "",
          price: data.price || "",
          quantity: data.quantity || "",
          categoryId: data.categoryId?._id || data.categoryId || "",
          productimage: null // file input always starts empty
        });
        // Show existing image as preview
        if (data.productimage) {
          setPreviewImage(`http://localhost:7000/image/${data.productimage}`);
        }
      })
      .catch((err) => console.log(err));
  }, [id]);

  // ✅ Handle all input changes including file
  const handleChange = (e) => {
    if (e.target.name === "productimage") {
      const file = e.target.files[0];
      setProduct({ ...product, productimage: file });
      setPreviewImage(URL.createObjectURL(file)); // live preview of new image
    } else {
      setProduct({ ...product, [e.target.name]: e.target.value });
    }
  };

  // ✅ Submit update using FormData (same as AddProduct)
  const handleUpdate = async () => {
    try {
      const formData = new FormData();
      formData.append("name", product.name);
      formData.append("description", product.description);
      formData.append("price", product.price);
      formData.append("quantity", product.quantity);
      formData.append("categoryId", product.categoryId);

      // Only append image if a new one was selected
      if (product.productimage) {
        formData.append("productimage", product.productimage);
      }

      const res = await axios.put(
        `http://localhost:7000/product/updateProduct/${id}`,
        formData
      );

      console.log(res.data);
      alert("Product Updated Successfully!");
      navigate("/Admin/ViewProduct"); // ✅ go back to product list

    } catch (error) {
      console.log(error);
      alert("Error updating product");
    }
  };

  return (
    <Container maxWidth="sm">
      <Paper elevation={4} sx={{ p: 4, mt: 5, borderRadius: 3 }}>

        <Typography variant="h5" align="center" gutterBottom>
          Update Product
        </Typography>

        <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>

          {/* Product Name */}
          <TextField
            label="Product Name"
            name="name"
            value={product.name}
            onChange={handleChange}
            fullWidth
            required
          />

          {/* Description */}
          <TextField
            label="Description"
            name="description"
            value={product.description}
            onChange={handleChange}
            fullWidth
            multiline
            rows={3}
            required
          />

          {/* Price */}
          <TextField
            label="Price"
            name="price"
            type="number"
            value={product.price}
            onChange={handleChange}
            fullWidth
            required
          />

          {/* Quantity */}
          <TextField
            label="Quantity"
            name="quantity"
            type="number"
            value={product.quantity}
            onChange={handleChange}
            fullWidth
            required
          />

          {/* Category Dropdown */}
          <FormControl fullWidth>
            <InputLabel>Category</InputLabel>
            <Select
              name="categoryId"
              value={product.categoryId}
              label="Category"
              onChange={handleChange}
            >
              <MenuItem value="">Select Category</MenuItem>
              {category.map((cat) => (
                <MenuItem key={cat._id} value={cat._id}>
                  {cat.categoryName}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* Existing Image Preview */}
          {previewImage && (
            <Box>
              <Typography variant="body2" sx={{ mb: 1, color: "gray" }}>
                Current Image:
              </Typography>
              <img
                src={previewImage}
                alt="product"
                width="120"
                style={{ borderRadius: 8, border: "1px solid #ddd" }}
              />
            </Box>
          )}

          {/* Image Upload */}
          <TextField
            label="Change Image (optional)"
            name="productimage"
            type="file"
            onChange={handleChange}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />

          {/* Submit Button */}
          <Button
            variant="contained"
            size="large"
            onClick={handleUpdate}
            sx={{ mt: 1, borderRadius: 2 }}
          >
            Update Product
          </Button>

        </Box>
      </Paper>
    </Container>
  );
}
